{"content":"package org.wordpress.android.ui.newstats.viewsstats

import androidx.lifecycle.SavedStateHandle
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.Job
import kotlinx.coroutines.async
import kotlinx.coroutines.coroutineScope
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import org.wordpress.android.R
import org.wordpress.android.fluxc.model.SiteModel
import org.wordpress.android.fluxc.store.AccountStore
import org.wordpress.android.ui.mysite.SelectedSiteRepository
import org.wordpress.android.ui.newstats.StatsPeriod
import org.wordpress.android.ui.newstats.analytics.NewStatsTracker
import org.wordpress.android.ui.newstats.datasource.StatsUnit
import org.wordpress.android.ui.newstats.repository.BottomStatsAggregates
import org.wordpress.android.ui.newstats.repository.BottomStatsResult
import org.wordpress.android.ui.newstats.repository.PeriodAggregates
import org.wordpress.android.ui.newstats.repository.PeriodStatsResult
import org.wordpress.android.ui.newstats.repository.StatsCacheBucket
import org.wordpress.android.ui.newstats.repository.StatsCardsConfigurationRepository
import org.wordpress.android.ui.newstats.repository.StatsRepository
import org.wordpress.android.ui.newstats.repository.ViewsDataPoint
import org.wordpress.android.ui.newstats.util.RangeYearPlacement
import org.wordpress.android.ui.newstats.util.rangeYearPlacement
import org.wordpress.android.util.AppLog
import org.wordpress.android.viewmodel.ResourceProvider
import java.time.LocalDate
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter
import java.time.temporal.ChronoUnit
import java.util.Locale
import javax.inject.Inject
import kotlin.math.abs

private const val PERCENTAGE_BASE = 100.0
private const val DAYS_THRESHOLD_FOR_MONTHLY_DISPLAY = 31
private const val DATE_PREFIX_LENGTH = 10 // "YYYY-MM-DD".length

private val HOURLY_FORMAT_REGEX = Regex("""\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}""")
private val DAILY_FORMAT_REGEX = Regex("""\d{4}-\d{2}-\d{2}""")
private val MONTHLY_FORMAT_REGEX = Regex("""\d{4}-\d{2}""")

private const val KEY_CHART_TYPE = "chart_type"
private const val KEY_METRIC = "selected_metric"
private const val KEY_ORIGIN_PERIOD_TYPE = "origin_period_type"
private const val KEY_ORIGIN_CUSTOM_START_DATE = "origin_custom_start_date"
private const val KEY_ORIGIN_CUSTOM_END_DATE = "origin_custom_end_date"

private val EMPTY_BOTTOM_AGGREGATES = BottomStatsAggregates(0L, 0L, 0L, 0L, 0L)

@HiltViewModel
class ViewsStatsViewModel @Inject constructor(
    private val selectedSiteRepository: SelectedSiteRepository,
    private val accountStore: AccountStore,
    private val statsRepository: StatsRepository,
    private val resourceProvider: ResourceProvider,
    private val savedStateHandle: SavedStateHandle,
    private val cardsConfigurationRepository: StatsCardsConfigurationRepository,
    private val tracker: NewStatsTracker
) : ViewModel() {
    private val _uiState = MutableStateFlow<ViewsStatsCardUiState>(ViewsStatsCardUiState.Loading)
    val uiState: StateFlow<ViewsStatsCardUiState> = _uiState.asStateFlow()

    private val _isRefreshing = MutableStateFlow(false)
    val isRefreshing: StateFlow<Boolean> = _isRefreshing.asStateFlow()

    private val _selectedPeriod = MutableStateFlow(restorePeriodFromSavedState())
    val selectedPeriod: StateFlow<StatsPeriod> = _selectedPeriod.asStateFlow()

    private val _effectivePeriod = MutableStateFlow(_selectedPeriod.value)

    /**
     * The period the rest of the screen should treat as current.
     *
     * It differs from [selectedPeriod] when the user paged away from a preset: the concrete window
     * is what data is loaded for, but the screen keeps showing the preset it came from until the
     * window stops matching that preset's current range. That is what keeps a rolling window rolling
     * even once its concrete dates happen to line up with a calendar month.
     */
    val effectivePeriod: StateFlow<StatsPeriod> = _effectivePeriod.asStateFlow()

    private var currentChartType: ChartType = restoreChartTypeFromSavedState()
    private var currentSelectedMetric: StatsMetric = restoreMetricFromSavedState()
    private var currentPeriod: StatsPeriod = _selectedPeriod.value
    private var periodOrigin: StatsPeriod = _selectedPeriod.value

    /**
     * Whether the user explicitly picked a metric while this period was active. Without an explicit
     * pick an hourly period quietly falls back to views; with one, the requested metric is answered
     * with an unavailable state instead.
     */
    private var metricPickedOnCurrentPeriod = false

    private var loadingPeriod: StatsPeriod? = null
    private var loadedPeriod: StatsPeriod? = null
    private var loadJob: Job? = null
    private var refreshJob: Job? = null

    private var loadedPeriodResult: PeriodStatsResult.Success? = null
    private var loadedBottomCurrent: BottomStatsAggregates = EMPTY_BOTTOM_AGGREGATES
    private var loadedBottomPrevious: BottomStatsAggregates = EMPTY_BOTTOM_AGGREGATES

    private val _isPeriodInitialized = MutableStateFlow(false)
    val isPeriodInitialized: StateFlow<Boolean> = _isPeriodInitialized.asStateFlow()

    private val _canNavigateBackward = MutableStateFlow(statsRepository.canNavigateBackward(currentPeriod))
    val canNavigateBackward: StateFlow<Boolean> = _canNavigateBackward.asStateFlow()

    private val _canNavigateForward = MutableStateFlow(statsRepository.canNavigateForward(currentPeriod))
    val canNavigateForward: StateFlow<Boolean> = _canNavigateForward.asStateFlow()

    init {
        initializeWithPersistedPeriod()
    }

    // region period

    /**
     * Initializes the ViewModel by restoring the period from persisted preferences asynchronously.
     * Data loading is deferred to [loadDataIfNeeded] which is called from the composable
     * only when the VIEWS_STATS card is visible.
     */
    private fun initializeWithPersistedPeriod() {
        viewModelScope.launch {
            if (savedStateHandle.get<String>(KEY_PERIOD_TYPE) == null) {
                val restored = restorePeriodFromPreferences()
                if (restored != null) {
                    currentPeriod = restored.period
                    periodOrigin = restored.origin
                    _selectedPeriod.value = restored.period
                    updateEffectivePeriod()
                    updateNavigationState()
                }
            } else {
                val restoredOrigin = restoreOriginFromSavedState()
                if (restoredOrigin != null) {
                    periodOrigin = restoredOrigin
                    updateEffectivePeriod()
                }
            }
            if (savedStateHandle.get<String>(KEY_CHART_TYPE) == null) {
                restoreChartTypeFromPreferences()?.let { currentChartType = it }
            }
            if (savedStateHandle.get<String>(KEY_METRIC) == null) {
                restoreMetricFromPreferences()?.let { currentSelectedMetric = it }
            }
            _isPeriodInitialized.value = true
        }
    }

    /** Restores the concrete period plus the preset family it was paged from. */
    private data class RestoredPeriod(val period: StatsPeriod, val origin: StatsPeriod)

    private suspend fun restorePeriodFromPreferences(): RestoredPeriod? {
        val siteId = selectedSiteRepository.getSelectedSite()?.siteId ?: return null
        val config = cardsConfigurationRepository.getConfiguration(siteId)
        val periodType = config.selectedPeriodType ?: return null
        val period = StatsPeriod.fromTypeString(
            type = periodType,
            customStartEpochDay = config.customPeriodStartDate,
            customEndEpochDay = config.customPeriodEndDate
        )
        val originType = config.originPeriodType ?: periodType
        val origin = StatsPeriod.fromTypeString(
            type = originType,
            customStartEpochDay = config.originCustomStartDate,
            customEndEpochDay = config.originCustomEndDate
        )
        return RestoredPeriod(period = period, origin = origin)
    }

    private fun restoreOriginFromSavedState(): StatsPeriod? {
        val originType = savedStateHandle.get<String>(KEY_ORIGIN_PERIOD_TYPE) ?: return null
        return StatsPeriod.fromTypeString(
            type = originType,
            customStartEpochDay = savedStateHandle.get<Long>(KEY_ORIGIN_CUSTOM_START_DATE),
            customEndEpochDay = savedStateHandle.get<Long>(KEY_ORIGIN_CUSTOM_END_DATE)
        )
    }

    /**
     * Loads data only if it hasn't been loaded (or isn't currently loading) for the current period.
     * Called from the composable when the VIEWS_STATS card is visible.
     */
    fun loadDataIfNeeded() {
        val targetPeriod = currentPeriod
        if (loadedPeriod == targetPeriod || loadingPeriod == targetPeriod) return
        loadingPeriod = targetPeriod
        loadData()
    }

    /** A preset is a fresh anchor: it replaces the origin the window was paged from. */
    fun onPresetSelected(period: StatsPeriod) {
        tracker.trackDateRangePresetSelected(period)
        periodOrigin = period
        onPeriodChanged(period, loadData = true)
    }

    /** An explicitly picked range has no preset family, so it becomes its own origin. */
    fun onCustomRangeSelected(start: LocalDate, end: LocalDate) {
        tracker.trackCustomDateRangeSelected(start, end)
        periodOrigin = StatsPeriod.Custom(start, end)
        onPeriodChanged(periodOrigin, loadData = true)
    }

    /**
     * Commits [period]. A preset becomes the new origin; a concrete window keeps the origin it was
     * paged from so paging stays within the same family.
     *
     * Everything that reads from the period — navigation state, the soft selection, the persisted
     * configuration — is updated together, so the visible surfaces can never disagree about which
     * period is current.
     */
    fun onPeriodChanged(period: StatsPeriod, loadData: Boolean = true) {
        if (period != StatsPeriod.Custom) {
            periodOrigin = period
        }
        if (period == currentPeriod) {
            if (loadData) loadDataIfNeeded()
            return
        }
        currentPeriod = period
        _selectedPeriod.value = period
        updateEffectivePeriod()
        updateNavigationState()
        clearSelection()
        savePeriod(period)
        if (loadData) {
            markLoadingNewPeriod()
            loadingPeriod = period
            loadData()
        }
    }

    /**
     * Pages the whole screen to the range immediately before the current one (see
     * [StatsRepository.previousPeriod]). Guarded by the same floor the button's enabled state uses,
     * so a stray tap on a disabled control is a no-op.
     */
    fun onNavigatePrevious() {
        if (!statsRepository.canNavigateBackward(currentPeriod)) return
        val target = statsRepository.previousPeriod(currentPeriod, periodOrigin)
        if (target == currentPeriod) return
        tracker.trackDateNavigationButtonTapped(NewStatsTracker.NavigationDirection.PREVIOUS, target)
        onPeriodChanged(target, loadData = true)
    }

    /**
     * Pages the whole screen to the range immediately after the current one (see
     * [StatsRepository.nextPeriod]). Guarded so a tap while at the present edge is a no-op.
     */
    fun onNavigateNext() {
        if (!statsRepository.canNavigateForward(currentPeriod)) return
        val target = statsRepository.nextPeriod(currentPeriod, periodOrigin)
        if (target == currentPeriod) return
        tracker.trackDateNavigationButtonTapped(NewStatsTracker.NavigationDirection.NEXT, target)
        onPeriodChanged(target, loadData = true)
    }

    private fun updateNavigationState() {
        _canNavigateBackward.value = statsRepository.canNavigateBackward(currentPeriod)
        _canNavigateForward.value = statsRepository.canNavigateForward(currentPeriod)
    }

    private fun updateEffectivePeriod() {
        val selected = currentPeriod
        val origin = periodOrigin
        val resolved = if (selected is StatsPeriod.Custom && origin != selected &&
            statsRepository.periodWindow(selected) == statsRepository.periodWindow(origin)
        ) {
            origin
        } else {
            selected
        }
        _effectivePeriod.value = resolved
    }

    private fun savePeriod(period: StatsPeriod) {
        savedStateHandle[KEY_PERIOD_TYPE] = period.toTypeString()
        if (period is StatsPeriod.Custom) {
            savedStateHandle[KEY_CUSTOM_START_DATE] = period.startDate.toEpochDay()
            savedStateHandle[KEY_CUSTOM_END_DATE] = period.endDate.toEpochDay()
        }
        val origin = periodOrigin
        savedStateHandle[KEY_ORIGIN_PERIOD_TYPE] = origin.toTypeString()
        if (origin is StatsPeriod.Custom) {
            savedStateHandle[KEY_ORIGIN_CUSTOM_START_DATE] = origin.startDate.toEpochDay()
            savedStateHandle[KEY_ORIGIN_CUSTOM_END_DATE] = origin.endDate.toEpochDay()
        }

        val siteId = selectedSiteRepository.getSelectedSite()?.siteId ?: return
        viewModelScope.launch {
            val config = cardsConfigurationRepository.getConfiguration(siteId)
            cardsConfigurationRepository.saveConfiguration(
                siteId,
                config.copy(
                    selectedPeriodType = period.toTypeString(),
                    customPeriodStartDate = (period as? StatsPeriod.Custom)?.startDate?.toEpochDay(),
                    customPeriodEndDate = (period as? StatsPeriod.Custom)?.endDate?.toEpochDay(),
                    originPeriodType = origin.toTypeString(),
                    originCustomStartDate = (origin as? StatsPeriod.Custom)?.startDate?.toEpochDay(),
                    originCustomEndDate = (origin as? StatsPeriod.Custom)?.endDate?.toEpochDay()
                )
            )
        }
    }

    /**
     * Restores period from SavedStateHandle only (fast, no disk I/O).
     * Used for property initialization.
     */
    private fun restorePeriodFromSavedState(): StatsPeriod {
        val savedPeriodType = savedStateHandle.get<String>(KEY_PERIOD_TYPE) ?: return StatsPeriod.Last7Days
        return StatsPeriod.fromTypeString(
            type = savedPeriodType,
            customStartEpochDay = savedStateHandle.get<Long>(KEY_CUSTOM_START_DATE),
            customEndEpochDay = savedStateHandle.get<Long>(KEY_CUSTOM_END_DATE)
        )
    }

    // endregion

    // region chart type & metric

    private fun restoreChartTypeFromSavedState(): ChartType {
        return ChartType.fromStorageKey(
            savedStateHandle.get<String>(KEY_CHART_TYPE)
        ) ?: ChartType.DEFAULT
    }

    private suspend fun restoreChartTypeFromPreferences(): ChartType? {
        val siteId = selectedSiteRepository.getSelectedSite()?.siteId
            ?: return null
        val config = cardsConfigurationRepository.getConfiguration(siteId)
        return ChartType.fromStorageKey(config.selectedChartType)
    }

    private fun restoreMetricFromSavedState(): StatsMetric {
        return StatsMetric.fromStorageKey(
            savedStateHandle.get<String>(KEY_METRIC)
        ) ?: StatsMetric.DEFAULT
    }

    private suspend fun restoreMetricFromPreferences(): StatsMetric? {
        val siteId = selectedSiteRepository.getSelectedSite()?.siteId
            ?: return null
        val config = cardsConfigurationRepository.getConfiguration(siteId)
        return StatsMetric.fromStorageKey(config.selectedMetric)
    }

    private fun saveChartType(chartType: ChartType) {
        savedStateHandle[KEY_CHART_TYPE] = chartType.storageKey

        val siteId = selectedSiteRepository.getSelectedSite()?.siteId
            ?: return
        viewModelScope.launch {
            val config =
                cardsConfigurationRepository.getConfiguration(siteId)
            cardsConfigurationRepository.saveConfiguration(
                siteId,
                config.copy(
                    selectedChartType = chartType.storageKey
                )
            )
        }
    }

    private fun saveMetric(metric: StatsMetric) {
        savedStateHandle[KEY_METRIC] = metric.storageKey

        val siteId = selectedSiteRepository.getSelectedSite()?.siteId
            ?: return
        viewModelScope.launch {
            val config = cardsConfigurationRepository.getConfiguration(siteId)
            cardsConfigurationRepository.saveConfiguration(
                siteId,
                config.copy(
                    selectedMetric = metric.storageKey
                )
            )
        }
    }

    /**
     * A chart-shape change re-interprets every bucket position, so any existing soft selection
     * points at a bucket the user never tapped and is dropped.
     */
    fun onChartTypeChanged(chartType: ChartType) {
        val from = currentChartType
        currentChartType = chartType
        if (from != chartType) {
            tracker.trackChartTypeChanged(from, chartType)
        }
        saveChartType(chartType)
        clearSelection()
        _uiState.update { current ->
            when {
                current is ViewsStatsCardUiState.Content && current.chart is ChartUiState.Loaded ->
                    current.copy(
                        chart = (current.chart as ChartUiState.Loaded).copy(chartType = chartType),
                        selectedBar = null
                    )
                current is ViewsStatsCardUiState.Content ->
                    current.copy(
                        selectedMetric = displayedMetric(),
                        selectedBar = null
                    )
                else -> current
            }
        }
    }

    /**
     * Records an explicit metric choice.
     *
     * The preference is stored immediately so it survives leaving the screen, and the chart is
     * re-derived from the response that is already loaded — the period response carries every
     * metric per bucket, so switching metrics never needs another fetch.
     */
    fun onMetricSelected(metric: StatsMetric) {
        currentSelectedMetric = metric
        metricPickedOnCurrentPeriod = true
        tracker.trackChartMetricSelected(metric)
        saveMetric(metric)
        applyChart()
    }

    // endregion

    // region bucket interaction

    /**
     * Soft-selects the tapped bucket: the chart stays on its committed period while the header,
     * the bottom row and the top range switch to the bucket's own values, reusing data that is
     * already loaded. Tapping the same bucket again clears the selection; tapping another moves it.
     *
     * Upcoming placeholders and any other non-actionable bucket never create a selection.
     */
    fun onBarTapped(index: Int) {
        val content = _uiState.value as? ViewsStatsCardUiState.Content ?: return
        if (content.isLoadingNewPeriod) return
        val chart = content.chart as? ChartUiState.Loaded ?: return
        val point = chart.chartData.currentPeriod.getOrNull(index) ?: return
        if (point.isUpcoming) return

        val existing = content.selectedBar
        if (existing != null && existing.index == index) {
            setSelectedBar(null)
            return
        }

        val selected = SelectedBar(
            index = index,
            label = point.label,
            canDrillDown = drillDownPeriod(point.rawPeriod) != null
        )
        tracker.trackChartBarSelected(content.selectedMetric, currentUnit(), point.value)
        setSelectedBar(selected)
    }

    /**
     * Commits the soft selection as the new period.
     *
     * The transient selection is dropped before the destination starts loading so no visible
     * surface keeps pointing at the bucket the user has already committed away from.
     */
    fun onDrillIntoSelectedBar() {
        val content = _uiState.value as? ViewsStatsCardUiState.Content ?: return
        if (content.isLoadingNewPeriod) return
        val bar = content.selectedBar ?: return
        if (!bar.canDrillDown) return
        val loaded = loadedPeriodResult ?: return
        val point = loaded.currentPeriodData.getOrNull(bar.index) ?: return
        val target = drillDownPeriod(point.period) ?: return
        _uiState.value = content.copy(selectedBar = null, isLoadingNewPeriod = true)
        onPeriodChanged(target, loadData = true)
    }

    private fun setSelectedBar(selectedBar: SelectedBar?) {
        val content = _uiState.value as? ViewsStatsCardUiState.Content ?: return
        if (content.selectedBar == selectedBar) return
        _uiState.value = content.copy(selectedBar = selectedBar)
        // Header, chart highlight and bottom row all describe the same bucket.
        applyChart()
        applyBottomStats()
    }

    /** Drops a soft selection that no longer refers to anything on screen. */
    private fun clearSelection() {
        val content = _uiState.value as? ViewsStatsCardUiState.Content ?: return
        if (content.selectedBar == null) return
        _uiState.value = content.copy(selectedBar = null)
        applyChart()
        applyBottomStats()
    }

    @Suppress("ReturnCount", "TooGenericExceptionCaught")
    private fun drillDownPeriod(rawPeriod: String): StatsPeriod? {
        // Hourly data — no smaller period available
        if (rawPeriod.matches(HOURLY_FORMAT_REGEX)) return null

        return try {
            val date = parsePeriodDate(rawPeriod) ?: return null
            if (isMonthlyGranularity(currentPeriod)) {
                val firstDay = date.withDayOfMonth(1)
                StatsPeriod.Custom(firstDay, firstDay.withDayOfMonth(firstDay.lengthOfMonth()))
            } else {
                StatsPeriod.Custom(date, date)
            }
        } catch (e: Exception) {
            AppLog.e(
                AppLog.T.STATS,
                "Failed to parse period for drill-down: $rawPeriod",
                e
            )
            null
        }
    }

    private fun isMonthlyGranularity(period: StatsPeriod): Boolean = when (period) {
        is StatsPeriod.Last12Months -> true
        is StatsPeriod.Custom ->
            ChronoUnit.DAYS.between(period.startDate, period.endDate) + 1 > DAYS_THRESHOLD_FOR_MONTHLY_DISPLAY
        else -> false
    }

    // endregion

    // region loading

    /**
     * Pull-to-refresh. Cached state is invalidated synchronously, before any refresh is dispatched,
     * so a request that was already in flight cannot write its older answer back over the refreshed
     * one. The indicator is owned by this refresh alone and therefore stops as soon as the refresh
     * itself completes, even if older competing work finishes later.
     */
    fun refresh() {
        val site = selectedSiteRepository.getSelectedSite() ?: return
        statsRepository.invalidateCache()
        clearSelection()
        cancelPendingLoads()
        loadingPeriod = currentPeriod
        refreshJob = viewModelScope.launch {
            try {
                _isRefreshing.value = true
                loadDataInternal(site, forceRefresh = true, isRefresh = true)
            } finally {
                _isRefreshing.value = false
            }
        }
    }

    private fun cancelPendingLoads() {
        loadJob?.cancel()
        loadJob = null
        refreshJob?.cancel()
        refreshJob = null
        _isRefreshing.value = false
    }

    fun loadData() {
        val site = selectedSiteRepository.getSelectedSite()
        if (site == null) {
            loadingPeriod = null
            _uiState.value = ViewsStatsCardUiState.Error(
                message = resourceProvider.getString(
                    R.string.stats_error_no_site
                )
            )
            return
        }

        val accessToken = accountStore.accessToken
        if (accessToken.isNullOrEmpty()) {
            loadingPeriod = null
            _uiState.value = ViewsStatsCardUiState.Error(
                message = resourceProvider.getString(
                    R.string.stats_error_api
                )
            )
            return
        }

        statsRepository.bindSite(site.siteId)
        val targetPeriod = currentPeriod
        val hasCachedContent = hasCachedContent(site, targetPeriod)
        val current = _uiState.value
        // While switching to a new period we keep the previous content on screen (dimmed, with a
        // spinner) instead of resetting to placeholders; likewise a cached revisit must not be
        // covered by a loading placeholder. Otherwise show per-region placeholders.
        if (!hasCachedContent && (current !is ViewsStatsCardUiState.Content || !current.isLoadingNewPeriod)) {
            _uiState.value = ViewsStatsCardUiState.Content(
                chart = ChartUiState.Loading,
                bottomStats = BottomStatsUiState.Loading,
                selectedMetric = displayedMetric()
            )
        }
        clearSelection()

        // Rapid paging ("back five days quickly") fires overlapping loads. Cancel the in-flight one so
        // only the latest period's request survives — otherwise a stale older coroutine can clear the
        // dim/loadingPeriod mid-flight (flicker) or write a stale loadedPeriod (a redundant refetch).
        loadJob?.cancel()
        loadJob = viewModelScope.launch {
            if (hasCachedContent) {
                revalidateIfNeeded(site, targetPeriod)
            } else {
                loadDataInternal(site, forceRefresh = false, isRefresh = false)
            }
        }
    }

    /**
     * Repaints from whatever the cache already holds and lets the repository refresh it in the
     * background. A failed refresh resolves back to the cached content rather than to an error, so
     * the user never loses usable data because of a background failure.
     */
    private suspend fun revalidateIfNeeded(site: SiteModel, period: StatsPeriod) {
        if (!statsRepository.isCached(StatsCacheBucket.CHART, site.siteId, period)) return
        loadDataInternal(site, forceRefresh = false, isRefresh = false)
    }

    private fun hasCachedContent(site: SiteModel, period: StatsPeriod): Boolean {
        if (!statsRepository.isCached(StatsCacheBucket.CHART, site.siteId, period)) return false
        return fillsBottomFromChart(period) ||
            statsRepository.isCached(StatsCacheBucket.BOTTOM_STATS, site.siteId, period)
    }

    /**
     * Loads the chart and the bottom-stats row concurrently and independently. Each updates only its
     * own region of the [ViewsStatsCardUiState.Content] state as it completes, so the chart can
     * appear before (or without) the bottom row and vice versa.
     */
    private suspend fun loadDataInternal(
        site: SiteModel,
        forceRefresh: Boolean,
        isRefresh: Boolean
    ) {
        val targetPeriod = currentPeriod
        val fillBottom = fillsBottomFromChart(targetPeriod)
        try {
            val loaded = if (fillBottom) {
                loadChart(site, targetPeriod, forceRefresh, isRefresh, true)
            } else {
                // Single-day periods fetch the bottom row from a dedicated day-level call (run in
                // parallel with the chart): their chart is hourly and an hourly response only
                // populates `views`, so it can't fill the row.
                coroutineScope {
                    val chart = async { loadChart(site, targetPeriod, forceRefresh, isRefresh, false) }
                    val bottom = async { loadBottomStats(site, targetPeriod, forceRefresh, isRefresh) }
                    val chartLoaded = chart.await()
                    val bottomLoaded = bottom.await()
                    chartLoaded && bottomLoaded
                }
            }
            // Treat the period as loaded only when everything shown succeeded; otherwise a transient
            // failure would leave loadedPeriod set and make loadDataIfNeeded short-circuit forever.
            if (loaded) {
                loadedPeriod = targetPeriod
            }
        } finally {
            // Only clear the flags if this load still owns them. A load superseded by rapid paging is
            // cancelled and its finally runs after the newer load has already set loadingPeriod to the
            // newer period, so clearing unconditionally here would wipe the newer load's dim.
            if (loadingPeriod == targetPeriod) {
                loadingPeriod = null
                clearLoadingNewPeriod()
            }
        }
    }

    /**
     * Clears the card-level [ViewsStatsCardUiState.Content.isLoadingNewPeriod] dim flag once both the
     * chart and the (independently, and often slower) bottom-row calls have completed. Clearing it here
     * rather than when the chart alone finishes prevents the previous period's bottom-row totals from
     * being shown un-dimmed as if they belonged to the new period.
     */
    private fun clearLoadingNewPeriod() {
        _uiState.update { current ->
            if (current is ViewsStatsCardUiState.Content && current.isLoadingNewPeriod) {
                current.copy(isLoadingNewPeriod = false)
            } else {
                current
            }
        }
    }

    private fun markLoadingNewPeriod() {
        val content = _uiState.value as? ViewsStatsCardUiState.Content ?: return
        if (!content.isLoadingNewPeriod) {
            _uiState.value = content.copy(isLoadingNewPeriod = true)
        }
    }

    /**
     * Loads the chart for [period]. When [fillBottomFromChart] is true the bottom row is filled
     * from the same response (its per-bucket data already carries all five metrics); when false the
     * bottom row is left untouched here because a dedicated call populates it (Today and Custom).
     */
    @Suppress("TooGenericExceptionCaught")
    private suspend fun loadChart(
        site: SiteModel,
        period: StatsPeriod,
        forceRefresh: Boolean,
        isRefresh: Boolean,
        fillBottomFromChart: Boolean
    ): Boolean {
        var success = false
        val metric = displayedMetric()
        val selectedBar = (_uiState.value as? ViewsStatsCardUiState.Content)?.selectedBar
        val chartState = try {
            when (val result = statsRepository.fetchStatsForPeriod(site.siteId, period, forceRefresh)) {
                is PeriodStatsResult.Success -> {
                    success = true
                    loadedPeriodResult = result
                    if (fillBottomFromChart) {
                        loadedBottomCurrent = result.currentAggregates.toBottomAggregates()
                        loadedBottomPrevious = result.previousAggregates.toBottomAggregates()
                        updateBottom(BottomStatsUiState.Loaded(buildStatItems(selectedBar)))
                    }
                    buildChartLoaded(result, metric, selectedBar)
                }
                is PeriodStatsResult.Error -> {
                    loadedPeriodResult = null
                    if (fillBottomFromChart) updateBottom(BottomStatsUiState.Hidden)
                    ChartUiState.Error
                }
            }
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            AppLog.e(AppLog.T.STATS, "Error loading views chart", e)
            loadedPeriodResult = null
            if (fillBottomFromChart) updateBottom(BottomStatsUiState.Hidden)
            ChartUiState.Error
        }
        updateChart(chartState, metric)
        return success
    }

    /**
     * Whether the bottom row can be filled from the chart's own response, which is true whenever the
     * chart isn't hourly: a non-hourly `stats/visits` response carries all five bottom-row metrics per
     * bucket, and the chart requests the same unit, quantity and windows the row needs.
     */
    private fun fillsBottomFromChart(period: StatsPeriod): Boolean = !isHourlyPeriod(period)

    /** Only single-day periods render an hourly chart, and an hourly chart only carries views. */
    private fun isHourlyPeriod(period: StatsPeriod): Boolean = when (period) {
        is StatsPeriod.Today -> true
        is StatsPeriod.Custom -> period.startDate == period.endDate
        else -> false
    }

    private fun supportsMetric(period: StatsPeriod, metric: StatsMetric): Boolean =
        !isHourlyPeriod(period) || metric == StatsMetric.VIEWS

    /** The metric actually drawn, which may be a fallback rather than the preference. */
    private fun chartMetric(): StatsMetric =
        if (supportsMetric(currentPeriod, currentSelectedMetric)) currentSelectedMetric else StatsMetric.DEFAULT

    private fun chartIsUnavailable(): Boolean =
        metricPickedOnCurrentPeriod && !supportsMetric(currentPeriod, currentSelectedMetric)

    /** The metric the visible surfaces are showing. */
    private fun displayedMetric(): StatsMetric =
        if (chartIsUnavailable()) currentSelectedMetric else chartMetric()

    private fun currentUnit(): StatsUnit = loadedPeriodResult?.unit ?: StatsUnit.DAY

    /** Maps the period aggregates (which already carry all five metrics) onto the bottom-row values. */
    private fun PeriodAggregates.toBottomAggregates() = BottomStatsAggregates(
        views = views,
        visitors = visitors,
        likes = likes,
        comments = comments,
        posts = posts
    )

    /** Fetches the bottom row from a dedicated call. Used for single-day periods. */
    @Suppress("TooGenericExceptionCaught")
    private suspend fun loadBottomStats(
        site: SiteModel,
        period: StatsPeriod,
        forceRefresh: Boolean,
        isRefresh: Boolean
    ): Boolean {
        var success = false
        val selectedBar = (_uiState.value as? ViewsStatsCardUiState.Content)?.selectedBar
        val bottomState = try {
            when (val result = statsRepository.fetchBottomStats(period, forceRefresh)) {
                is BottomStatsResult.Success -> {
                    success = true
                    loadedBottomCurrent = result.current
                    loadedBottomPrevious = result.previous
                    BottomStatsUiState.Loaded(buildStatItems(selectedBar))
                }
                is BottomStatsResult.Error -> BottomStatsUiState.Hidden
            }
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            AppLog.e(AppLog.T.STATS, "Error loading bottom stats", e)
            BottomStatsUiState.Hidden
        }
        updateBottom(bottomState)
        return success
    }

    /**
     * Applies a chart-region update, preserving the current bottom-row state. The card-level
     * [ViewsStatsCardUiState.Content.isLoadingNewPeriod] dim flag is intentionally left untouched here;
     * it is cleared by [clearLoadingNewPeriod] only once both regions have finished loading.
     */
    private fun updateChart(chart: ChartUiState, metric: StatsMetric) {
        _uiState.update { current ->
            when (current) {
                is ViewsStatsCardUiState.Content ->
                    current.copy(chart = chart, selectedMetric = metric)
                else -> ViewsStatsCardUiState.Content(
                    chart = chart,
                    bottomStats = BottomStatsUiState.Loading,
                    selectedMetric = metric
                )
            }
        }
    }

    /** Applies a bottom-row update, preserving the current chart state. */
    private fun updateBottom(bottom: BottomStatsUiState) {
        _uiState.update { current ->
            when (current) {
                is ViewsStatsCardUiState.Content -> current.copy(bottomStats = bottom)
                else -> ViewsStatsCardUiState.Content(
                    chart = ChartUiState.Loading,
                    bottomStats = bottom,
                    selectedMetric = displayedMetric()
                )
            }
        }
    }

    /** Recomputes only the chart region, e.g. after a metric change. */
    private fun applyChart() {
        val loaded = loadedPeriodResult
        val content = _uiState.value as? ViewsStatsCardUiState.Content
        val metric = displayedMetric()
        val state = when {
            loaded == null -> ChartUiState.Loading
            chartIsUnavailable() -> ChartUiState.Unavailable
            else -> buildChartLoaded(loaded, metric, content?.selectedBar)
        }
        updateChart(state, metric)
    }

    /** Recomputes only the bottom row, e.g. after the soft selection moved. */
    private fun applyBottomStats() {
        val content = _uiState.value as? ViewsStatsCardUiState.Content
        updateBottom(BottomStatsUiState.Loaded(buildStatItems(content?.selectedBar)))
    }

    private fun buildChartLoaded(
        result: PeriodStatsResult.Success,
        metric: StatsMetric,
        selectedBar: SelectedBar?
    ): ChartUiState.Loaded {
        val currentStats = result.currentAggregates
        val previousStats = result.previousAggregates
        val currentDataPoints = result.currentPeriodData.map { it.toChartPoint(metric, result.unit) }
        val previousDataPoints = result.previousPeriodData.map { it.toChartPoint(metric, result.unit) }

        val bucketIndex = selectedBar?.index
        val currentBucket = bucketIndex?.let { currentDataPoints.getOrNull(it) }
        val previousBucket = bucketIndex?.let { previousDataPoints.getOrNull(it) }

        val currentTotal = currentBucket?.value ?: currentStats.metricValue(metric)
        val previousTotal = previousBucket?.value ?: previousStats.metricValue(metric)

        val currentRange = if (currentBucket != null) {
            formatBucketRange(currentBucket.rawPeriod, result.unit)
        } else {
            formatDateRangeForPeriod(currentStats.startDate, currentStats.endDate, currentPeriod, result.unit)
        }
        val previousRange = if (previousBucket != null) {
            formatBucketRange(previousBucket.rawPeriod, result.unit)
        } else {
            formatDateRangeForPeriod(previousStats.startDate, previousStats.endDate, currentPeriod, result.unit)
        }

        // Upcoming placeholders keep the current period's shape but are not elapsed time, so they
        // are left out of the average instead of dragging it towards zero.
        val elapsedBuckets = currentDataPoints.count { !it.isUpcoming }.coerceAtLeast(1)
        val average = if (currentBucket != null) {
            currentBucket.value
        } else {
            currentTotal / elapsedBuckets
        }

        return ChartUiState.Loaded(
            currentPeriodTotal = currentTotal,
            previousPeriodTotal = previousTotal,
            difference = currentTotal - previousTotal,
            percentageChange = calculatePercentageChange(currentTotal, previousTotal),
            currentPeriodDateRange = currentRange,
            previousPeriodDateRange = previousRange,
            chartData = ViewsStatsChartData(currentPeriod = currentDataPoints, previousPeriod = previousDataPoints),
            periodAverage = average,
            chartType = currentChartType
        )
    }

    private fun ViewsDataPoint.toChartPoint(metric: StatsMetric, unit: StatsUnit) = ChartDataPoint(
        label = formatDataPointLabel(period, unit),
        value = metricValue(metric),
        rawPeriod = period,
        isUpcoming = isUpcoming
    )

    private fun ViewsDataPoint.metricValue(metric: StatsMetric): Long = when (metric) {
        StatsMetric.VIEWS -> views
        StatsMetric.VISITORS -> visitors
        StatsMetric.LIKES -> likes
        StatsMetric.COMMENTS -> comments
        StatsMetric.POSTS -> posts
    }

    private fun PeriodAggregates.metricValue(metric: StatsMetric): Long = when (metric) {
        StatsMetric.VIEWS -> views
        StatsMetric.VISITORS -> visitors
        StatsMetric.LIKES -> likes
        StatsMetric.COMMENTS -> comments
        StatsMetric.Posts -> posts
    }

    private fun BottomStatsAggregates.metricValue(metric: StatsMetric): Long = when (metric) {
        StatsMetric.VIEWS -> views
        StatsMetric.VISITORS -> visitors
        StatsMetric.LIKES -> likes
        StatsMetric.COMMENTS -> comments
        StatsMetric.Posts -> posts
    }

    /**
     * The bottom row always offers every metric, independently of what the chart can draw: the row
     * is the metric selector, and it stays usable even when the chart answers "unavailable".
     *
     * With a soft selection active every row describes that bucket instead of the whole period, so
     * the row, the chart header and the top range always agree.
     */
    private fun buildStatItems(selectedBar: SelectedBar?): List<StatItem> {
        val loaded = loadedPeriodResult
        val bucketIndex = selectedBar?.index
        val bucketCurrent = bucketIndex?.let { loaded?.currentPeriodData?.getOrNull(it) }
        val bucketPrevious = bucketIndex?.let { loaded?.previousPeriodData?.getOrNull(it) }
        return StatsMetric.entries.map { metric ->
            val value = bucketCurrent?.metricValue(metric) ?: loadedBottomCurrent.metricValue(metric)
            val previous = bucketPrevious?.metricValue(metric) ?: loadedBottomPrevious.metricValue(metric)
            StatItem(metric, value, calculateStatChange(value, previous))
        }
    }

    private fun calculateStatChange(current: Long, previous: Long): StatChange {
        if (current == previous) return StatChange.NoChange

        val percentage = calculatePercentageChange(current, previous)
        return if (current > previous) {
            StatChange.Positive(percentage)
        } else {
            StatChange.Negative(abs(percentage))
        }
    }

    private fun calculatePercentageChange(current: Long, previous: Long): Double {
        if (previous == 0L) return if (current > 0) PERCENTAGE_BASE else 0.0
        return ((current - previous).toDouble() / previous) * PERCENTAGE_BASE
    }

    // endregion

    // region formatting

    /**
     * Formats one chart bucket's axis label. The output granularity comes from [unit] — the
     * granularity the buckets were actually requested at — not from the [period] string, which is a
     * full ISO date for DAY, MONTH and YEAR buckets alike and so cannot be told apart on its own.
     * The string's shape still decides how to *parse* it, since the API returns "yyyy-MM" for some
     * month buckets and "yyyy-MM-dd" for others.
     */
    private fun formatDataPointLabel(period: String, unit: StatsUnit): String = when {
        period.matches(HOURLY_FORMAT_REGEX) -> formatHourlyLabel(period)
        else -> parsePeriodDate(period)
            ?.format(DateTimeFormatter.ofPattern(labelPatternFor(unit), Locale.getDefault()))
            ?: period
    }

    private fun labelPatternFor(unit: StatsUnit): String = when (unit) {
        StatsUnit.YEAR -> "yyyy"
        StatsUnit.MONTH -> "MMM"
        else -> "MMM d"
    }

    /** Parses a bucket's period string, tolerating both the "yyyy-MM" and "yyyy-MM-dd" shapes. */
    private fun parsePeriodDate(period: String): LocalDate? = when {
        period.matches(DAILY_FORMAT_REGEX) -> LocalDate.parse(period, DateTimeFormatter.ISO_LOCAL_DATE)
        period.matches(MONTHLY_FORMAT_REGEX) -> {
            val parts = period.split("-")
            LocalDate.of(parts[0].toInt(), parts[1].toInt(), 1)
        }
        else -> null
    }

    private fun formatHourlyLabel(period: String): String {
        val inputFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss", Locale.getDefault())
        val outputFormat = DateTimeFormatter.ofPattern("HH:mm", Locale.getDefault())
        return LocalDateTime.parse(period, inputFormat).format(outputFormat)
    }

    private fun isCustomPeriodMonthly(custom: StatsPeriod.Custom): Boolean {
        val daysBetween = ChronoUnit.DAYS.between(custom.startDate, custom.endDate) + 1
        return daysBetween > DAYS_THRESHOLD_FOR_MONTHLY_DISPLAY
    }

    /** Renders the range a single selected bucket covers, at that bucket's own granularity. */
    private fun formatBucketRange(rawPeriod: String, unit: StatsUnit): String {
        val date = parsePeriodDate(rawPeriod) ?: return rawPeriod
        return when (unit) {
            StatsUnit.YEAR -> formatYearRange(rawPeriod, rawPeriod)
            StatsUnit.MONTH -> formatMonthRange(rawPeriod, rawPeriod)
            else -> formatSingleDayRange(rawPeriod)
        }
    }

    /**
     * Formats the legend's date range. A YEAR-unit window is decided by [unit] rather than by
     * [period], because a Custom range long enough to be charted in years would otherwise fall into
     * the month branch and render a span like "Jan - Jun" for 2024→2026.
     */
    private fun formatDateRangeForPeriod(
        startDate: String,
        endDate: String,
        period: StatsPeriod,
        unit: StatsUnit
    ): String {
        if (unit == StatsUnit.YEAR) return formatYearRange(startDate, endDate)
        return when (period) {
            is StatsPeriod.Today -> formatSingleDayRange(endDate)
            is StatsPeriod.Last12Months -> formatMonthRange(startDate, endDate)
            is StatsPeriod.ThisWeek, is StatsPeriod.ThisMonth, is StatsPeriod.ThisYear ->
                formatDayRange(startDate, endDate)
            is StatsPeriod.Custom -> {
                if (isCustomPeriodMonthly(period)) formatMonthRange(startDate, endDate)
                else formatDayRange(startDate, endDate)
            }
            else -> formatDayRange(startDate, endDate)
        }
    }

    private fun formatSingleDayRange(date: String): String {
        val parsedDate = parsePeriodDate(date) ?: return date
        return parsedDate.format(DateTimeFormatter.ofPattern("d MMM yyyy", Locale.getDefault()))
    }

    @Suppress("ReturnCount")
    private fun formatYearRange(startDate: String, endDate: String): String {
        val start = parsePeriodDate(startDate) ?: return "$startDate - $endDate"
        val end = parsePeriodDate(endDate) ?: return "$startDate - $endDate"

        return if (start.year == end.year) "${start.year}" else "${start.year} - ${end.year}"
    }

    @Suppress("ReturnCount")
    private fun formatMonthRange(startDate: String, endDate: String): String {
        val start = parsePeriodDate(startDate) ?: return "$startDate - $endDate"
        val end = parsePeriodDate(endDate) ?: return "$startDate - $endDate"
        val monthFormat = DateTimeFormatter.ofPattern("MMM", Locale.getDefault())
        val monthYearFormat = DateTimeFormatter.ofPattern("MMM yyyy", Locale.getDefault())

        return when (rangeYearPlacement(start.year, end.year)) {
            // Cross-year span: show the year on both ends ("Dec 2024 - Jan 2025").
            RangeYearPlacement.BOTH -> "${start.format(monthYearFormat)} - ${end.format(monthYearFormat)}"
            // Same year: show the year once, on the trailing month ("Jan - Jun 2024").
            RangeYearPlacement.TRAILING ->
                if (start.month == end.month) start.format(monthYearFormat)
                else "${start.format(monthFormat)} - ${end.format(monthYearFormat)}"
        }
    }

    @Suppress("ReturnCount")
    private fun formatDayRange(startDate: String, endDate: String): String {
        val start = parsePeriodDate(startDate) ?: return "$startDate - $endDate"
        val end = parsePeriodDate(endDate) ?: return "$startDate - $endDate"
        val dayFormat = DateTimeFormatter.ofPattern("d", Locale.getDefault())
        val dayMonthFormat = DateTimeFormatter.ofPattern("d MMM", Locale.getDefault())
        val dayMonthYearFormat = DateTimeFormatter.ofPattern("d MMM yyyy", Locale.getDefault())

        return when (rangeYearPlacement(start.year, end.year)) {
            // Cross-year span: show the year on both ends ("28 Dec 2024 - 3 Jan 2025").
            RangeYearPlacement.BOTH ->
                "${start.format(dayMonthYearFormat)} - ${end.format(dayMonthYearFormat)}"
            // Same year: show the year once, on the trailing date. Collapse the leading month when
            // both ends share it ("14-20 Jan 2024" vs "28 Jul - 3 Aug 2024").
            RangeYearPlacement.TRAILING ->
                if (start.month == end.month) "${start.format(dayFormat)}-${end.format(dayMonthYearFormat)}"
                else "${start.format(dayMonthFormat)} - ${end.format(dayMonthYearFormat)}"
        }
    }

    // endregion

    /**
     * Recovers from a failed load.
     *
     * Only the regions that actually failed are retried, so a still-good chart is not replaced by a
     * loading placeholder while an unrelated region recovers.
     */
    fun onRetry() {
        val site = selectedSiteRepository.getSelectedSite() ?: return
        val content = _uiState.value as? ViewsStatsCardUiState.Content
        val chartFailed = content != null && content.chart is ChartUiState.Error
        val bottomFailed = content != null && content.bottomStats is BottomStatsUiState.Hidden
        if (content == null || (!chartFailed && !bottomFailed)) {
            // Nothing is visibly broken: this is a retry of a background refresh that did not land.
            loadingPeriod = currentPeriod
            loadData()
            return
        }

        val targetPeriod = currentPeriod
        val fillBottom = fillsBottomFromChart(targetPeriod)
        loadingPeriod = targetPeriod
        loadJob?.cancel()
        loadJob = viewModelScope.launch {
            var recovered = false
            if (chartFailed) {
                recovered = loadChart(site, targetPeriod, false, false, fillBottom) || recovered
            }
            if (bottomFailed && !fillBottom) {
                recovered = loadBottomStats(site, targetPeriod, false, false) || recovered
            }
            if (recovered) {
                loadedPeriod = targetPeriod
            }
            if (loadingPeriod == targetPeriod) {
                loadingPeriod = null
                clearLoadingNewPeriod()
            }
        }
    }

    companion object {
        /**
         * Keys used to restore the selected period. They double as Intent extras: Hilt seeds the
         * [SavedStateHandle] from the launching Intent, so an entry point can open New Stats on a
         * specific period without persisting it as the user's preference.
         */
        const val KEY_PERIOD_TYPE = "period_type"
        const val KEY_CUSTOM_START_DATE = "custom_start_date"
        const val KEY_CUSTOM_END_DATE = "custom_end_date"
    }
