suspend fun fetchMostViewed(
        siteId: Long,
        period: StatsPeriod,
        source: MostViewedDataSource = MostViewedDataSource.POSTS_AND_PAGES,
        forceRefresh: Boolean = false
    ): MostViewedResult {
        val dataSource = statsDataSource ?: return MostViewedResult.Error(StatsErrorType.API_ERROR.name)
        val range = calculateCurrentDateRange(period)
        val bucket = if (source == MostViewedDataSource.REFERRERS) {
            StatsCacheBucket.REFERRERS_DETAIL
        } else {
            StatsCacheBucket.MOST_VIEWED
        }
        val key = cacheKey(bucket, siteId, period, source.name)
        val generation = cache.currentGeneration
        val raw = cachedRaw(
            key = key,
            forceRefresh = forceRefresh,
            isUsable = { true },
            fetcher = {
                withContext(ioDispatcher) {
                    when (source) {
                        MostViewedDataSource.POSTS_AND_PAGES ->
                            dataSource.fetchTopPostsAndPages(siteId, range)
                        MostViewedDataSource.REFERRERS ->
                            dataSource.fetchReferrers(siteId, range)
                    }
                }
            }
        )
        if (generation != cache.currentGeneration) {
            // The cache was invalidated while this request was in flight; keep using the answer
            // locally but do not let it repopulate the refreshed state.
            return mostViewedSuccess(raw)
        }
        return mostViewedSuccess(raw)
    }

    @Suppress("UNCHECKED_CAST")
    private fun mostViewedSuccess(raw: Any): MostViewedResult {
        val items = raw as List<MostViewedItemData>
        val total = items.sumOf { it.views }
        return MostViewedResult.Success(items, total, 0L, 0.0)
    }

